def bachgold(n):
    dp = [0] * (n + 1)
    prime_factors = [[] for _ in range(n + 1)]

    for i in range(2, n + 1):
        if len(prime_factors[i]) == 0:
            for j in range(i, n + 1, i):
                if len(prime_factors[j]) == 0:
                    prime_factors[j].append(i)
                else:
                    prime_factors[j].extend([i] * (len(prime_factors[j]) - 1))

    dp[0], dp[1] = 0, 0

    for i in range(2, n + 1):
        dp[i] = dp[i - 1]
        for factor in prime_factors[i]:
            if i - factor >= 0:
                dp[i] = max(dp[i], dp[i - factor] + 1)

    result = []
    while n > 0:
        for factor in prime_factors[n]:
            if n - factor >= 0 and dp[n] == dp[n - factor] + 1:
                result.append(factor)
                n -= factor
                break

    return dp[-1], result

