def bachgold(n):
    def is_prime(num):
        if num <= 1:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    primes = [i for i in range(2, n+1) if is_prime(i)]

    result = []
    while n > 0:
        for prime in reversed(primes):
            if prime <= n:
                result.append(prime)
                n -= prime
                break

    print(len(result))
    print(' '.join(map(str, result)))

